  border-bottom: 1px solid #f1f5f9;
  color: #334155;
  font-size: 0.925rem;
}

.table-custom tbody tr {
  transition: background-color 0.15s ease;
}

.table-custom tbody tr:hover {
  background-color: #f8fafc;
}

/* Status Badges */
.badge-status {
  padding: 0.35rem 0.75rem;
  font-size: 0.75rem;
