.badge-status.badge-inativo {
  background-color: #f1f5f9;
  color: #64748b;
}
.badge-status.badge-inativo::before { background-color: #94a3b8; }

/* ==========================================================================
   BUTTONS & FORMS
   ========================================================================== */

.btn-primary-custom {
  background: linear-gradient(135deg, #4263a3, #19449c);
