    z-index: 1035;
  }
  .sidebar-backdrop.show {
    display: block;
  }
  .page-container {
    padding: 1.25rem 1rem;
  }
}

/* ==========================================================================
   DIGITALNET MS - TEMA AZUL TELECOM & AMARELO FIBRA
   ========================================================================== */

:root {
  --dn-blue: #1b4f99;
  --dn-blue-dark: #0f2d57;
  --dn-blue-deep: #091c36;
  --dn-blue-light: #eff6ff;
  --dn-blue-border: #bfdbfe;
  
  --dn-yellow: #f59e0b;
  --dn-yellow-gold: #ffbe18;
