}
.dn-kpi-card .kpi-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #64748b;
  margin-bottom: 0.25rem;
}

/* Tabela de Leads */
.dn-table-header {
  background: linear-gradient(135deg, var(--dn-blue-deep), var(--dn-blue));
  color: #ffffff;
}
.dn-table-header th {
  font-weight: 600;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.85rem 1rem;
