echo -e "  ${YELLOW}python3 wsgi.py${NC}"
echo -e "\nAcesse no navegador: ${BLUE}http://localhost:5000${NC}"
echo -e "Usuário: ${YELLOW}admin${NC} — senha exibida acima pelo seed (ou a definida em SEED_ADMIN_PASSWORD)."
